"""A reviewable report that preserves failed gates and source approximations."""
from pathlib import Path
from datetime import datetime,timezone
import csv,html,json,os
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'outputs/projects/proje-e9319baef1';REP=OUT/'reports'
def read(p):return json.loads(p.read_text())
def rel(p):return os.path.relpath(p,REP).replace('\\','/')
def link(p,label):return f'<a href="{html.escape(rel(p))}">{html.escape(label)}</a>'
def main():
    a=read(REP/'m6_jst_control_results_20261024_v2.json');b=read(REP/'m6_wallnormal_results_20261024_v3.json')
    old=read(OUT/'simulations/m6_bounded_cfl_20261019_123823/results.json');mesh=read(OUT/'simulations/m6_wallnormal_mesh_20261024_v3/normal_mesh_audit.json')
    f0=read(REP/'m6_baseline_force_integral_20261024.json');f1=read(REP/'m6_jst_force_integral_20261024_v2.json');f2=read(REP/'m6_wallnormal_force_integral_20261024_v3.json')
    rows=''
    labels=['Önceki Roe / kaynak ağ','JST / kaynak ağ','JST / konumsal normal ağ']
    metrics=[{'CL':old['CL'],'CD':old['CD'],'density_log10':old['density_log10'],'CL_last100_range':old['CL_last100_range'],'CD_last100_range':old['CD_last100_range']},a['matched'],b['matched']]
    cp=[a['baseline_Cp'],a['Cp'],b['Cp']]
    for label,m,c in zip(labels,metrics,cp):
        n=sum(s['Cp_RMSE']<.08 for s in c['sections'])
        rows+=f'<tr><td>{label}</td><td>{m["CL"]:.6f}<br>{m["CD"]:.7f}</td><td>{m["density_log10"]:.5f}</td><td>{m["CL_last100_range"]:.3g}<br>{m["CD_last100_range"]:.3g}</td><td>{c["yplus_max"]:.4f}</td><td>{c["all_point_Cp_RMSE"]:.5f}</td><td>{n}/14</td></tr>'
    gate_rows=''
    for name,key in [('İteratif kabul','iteration_passed'),('Max y+ < 1','wall_passed'),('14 kesit/yüzey RMSE < 0,08','experiment_passed')]:
        gate_rows+=f'<tr><td>{name}</td><td>{"geçti" if a[key] else "geçmedi"}</td><td>{"geçti" if b[key] else "geçmedi"}</td></tr>'
    section_rows=''
    for x,y,z in zip(a['baseline_Cp']['sections'],a['Cp']['sections'],b['Cp']['sections']):
        section_rows+=f'<tr><td>{x["section"]} / {x["eta"]:g}</td><td>{"üst" if x["side"]=="u" else "alt"}</td><td>{x["points"]}</td><td>{x["Cp_RMSE"]:.5f}</td><td>{y["Cp_RMSE"]:.5f}</td><td>{z["Cp_RMSE"]:.5f}</td></tr>'
    force_rows=''
    for label,f in zip(labels,[f0,f1,f2]):force_rows+=f'<tr><td>{label}</td><td>{f["CD_pressure"]:.7f}</td><td>{f["CD_viscous"]:.7f}</td><td>{100*f["CL_relative_difference"]:.4f}%</td><td>{100*f["CD_relative_difference"]:.4f}%</td></tr>'
    v1=read(REP/'m6_field_view_main_20261024_v2.json');v2=read(REP/'m6_field_view_normal_20261024_v2.json')
    assets=[(REP/'m6_jst_control_results_20261024_v2.json','JST sonuç/kalite kaydı'),(REP/'m6_wallnormal_results_20261024_v3.json','Normal ağ sonuç/kalite kaydı'),
        (REP/'m6_jst_prediction_frozen_20261024_v2.json','JST tahmin mührü'),(REP/'m6_wallnormal_prediction_frozen_20261024_v3.json','Normal ağ tahmin mührü'),
        (OUT/'data/m6_jst_control_20261024_v2/prediction/experimental_comparison.csv','JST: bütün271 nokta'),(OUT/'data/m6_jst_wallnormal_20261024_v3/prediction/experimental_comparison.csv','Normal ağ: bütün271 nokta'),
        (ROOT/v1['POS'],'JST gerçek Gmsh yüzey alanı'),(ROOT/v2['POS'],'Normal ağ gerçek Gmsh yüzey alanı'),
        (OUT/'simulations/m6_jst_control_20261024_v2'/f'flow_{a["matched"]["field_iteration"]:06d}.vtu','JST tam3B hacim alanı'),
        (OUT/'simulations/m6_jst_wallnormal_20261024_v3'/f'flow_{b["matched"]["field_iteration"]:06d}.vtu','Normal ağ tam3B hacim alanı')]
    assets.append((REP/'m6_reference_recheck_20261024.json','NASA Tecplot dosyasının yeni indirmeyle bayt eşleşmesi'))
    assets_html='<ul>'+''.join('<li>'+link(p,label)+'</li>' for p,label in assets)+'</ul>'
    now=datetime.now(timezone.utc).isoformat()
    doc=f'''<!doctype html><html lang="tr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>24 Ekim: RAE ve ONERA M6 gerçek testleri</title>
<style>body{{margin:0;background:#f1f5f7;color:#183044;font:16px/1.6 Segoe UI,Arial,sans-serif}}main{{max-width:1120px;margin:auto;padding:28px}}section{{background:white;border:1px solid #dce5eb;border-radius:12px;padding:24px;margin:20px 0}}h1{{font-size:30px;line-height:1.25}}h2{{font-size:22px}}table{{width:100%;border-collapse:collapse;font-size:13px}}th,td{{padding:10px;text-align:left;border-bottom:1px solid #dbe3ea;vertical-align:top}}th{{background:#edf3f7}}img{{max-width:100%;height:auto}}.bad{{background:#fee5df;color:#8e2f20;padding:12px;border-radius:8px;font-weight:600}}.note{{background:#eaf3f8;padding:14px;border-left:4px solid #4083a5}}.scroll{{overflow:auto}}a{{color:#17618e}}small{{color:#607584}}</style>
<main><h1>RAE testleri kapandı; ONERA M6 gerçek3B CFD ile sınandı</h1><p>24 Ekim2026 · Ayrı benchmark projesi: ONERA M6 · Gerçek İHA girdileri korunuyor.</p><p class="bad">Asgari genel yeterlilik: GEÇMEDİ. Başarılı program çıkışı ve geçen tek kapı, bütün doğrulama değildir.</p>
<section><h2>Ne yapıldı?</h2><p>Önce RAE2822 araştırma/test paketi14 native deneme kaydıyla dondurulup kapatıldı. Ardından kaynak ONERA M6 kanadında iki yeni3B sıkıştırılabilir RANS/SA koşusu çalıştırıldı. Kanat internetteki özgün SU2 kaynak ağından geliyor; yeniden tasarlanmadı. NASA'nın barındırdığı Schmitt–Charpin ONERA deneyiyle bütün271 basınç noktası karşılaştırıldı.</p><p>{link(ROOT/'outputs/projects/proje-15cce2de02/reports/v3_research_diagnosis.html','RAE kaynak araştırması, C-grid ve başarısızlık raporu')} · {link(ROOT/'outputs/projects/proje-15cce2de02/reports/v3_test_batch_closed.json','M6 başlamadan önceki kapanış kaydı')}</p><p>Koşullar önceden sabit: M=0,8395, alfa=3,06°, beta=0°, Re=11,72milyon, referans veter0,64607m.288,15K sıcaklık önceki kaynak örneğin hesap koşuludur; tünelde ölçülmüş sıcaklık diye sunulmuyor. Yarım kanat adyabatik/no-slip, kök simetri ve uzak alan kullanıldı. Ref alan0,76131555m² ve moment merkezi(0,25;0;0)m korundu.</p><p>Birinci yeni test aynı ağda Roe/MUSCL→JST politikasını sınar. İkinci test aynı JST config ve aynı başlangıç dosyasıyla yalnız iç duvar-normal noktalarını değiştirir. Kaydırılmış noktaya aynı indeksle atanan eski alan başlangıç tahminidir; tekrar yakınsama zorunludur.3.000'adım koşular dört CPU iş parçacığıyla gerçekten çalıştı.</p></section>
<section><h2>Ölçülen sonuçlar</h2><div class="scroll"><table><tr><th>Vaka</th><th>CL / CD</th><th>Yoğunluk log kalıntısı</th><th>Son100 CL / CD aralığı</th><th>Max y+</th><th>271-nokta Cp RMSE</th><th>Geçen kesit/yüzey</th></tr>{rows}</table></div><p>CL/CD sayısal kuvvetlerdir; bu arşivde deneysel kuvvet kıyası yapılmadı. Deney kıyası Cp'ye aittir. “Daha düşük CD” daha iyi kanat tasarımı demek değildir; kanat sabit, sayısal yöntem/ağ değişiyor.</p><table><tr><th>Ayrı kabul kapısı</th><th>JST kaynak ağ</th><th>JST normal ağ</th></tr>{gate_rows}<tr><td>Aynı geometride üç sistematik ağ / bölgesel BL / uzak alan</td><td>açık</td><td>açık</td></tr><tr><td>Genel kabul</td><td>geçmedi</td><td>geçmedi</td></tr></table><p>Eski M6 eşikleri değişmedi: log yoğunluk&lt;−7, son100 CL aralığı&lt;2e−4, CD aralığı&lt;2e−5; maxy+&lt;1 ve her14 kesit/yüzeyde CpRMSE&lt;0,08. NASA'nın±0,02 ölçüm belirsizliği ayrı bilgidir; evrensel CFD kabul eşiği yapılmadı.</p></section>
<section><h2>Hücre sayısı yerine konuma göre normal aralık</h2><p>Her iki yeni ağda258.969hücre ve100.592düğüm var.3.290 duvar-normal sütun bulundu;25 katman ve kaynak dış katman arayüzü korundu. Eski kendi y+ alanına göre ilk aralık yerel olarak azaltıldı; hedef tasarım y+0,5. Medyan ilk mesafe{1e6*mesh['first_normal_m_before']['median']:.3f}→{1e6*mesh['first_normal_m_after']['median']:.3f}µm. Kaynak kanat/uzak alan noktaları ve bütün hücre bağlantıları bit düzeyinde aynı;95.344 tetrahedronun noktaları da değişmedi.</p><p>Prizma Jacobian minimumu kaynakta{mesh['source_minimum_wedge_jacobian']:.4g}, yeni ağda{mesh['new_minimum_wedge_jacobian']:.4g};163.625 prizmada katlanma bulunmadı. SU2'nin düğüm/yüz yönelimine göre tek sabit referans dönüşümü kullanıldı. Yanlış işaretli hücreyi tek tek çevirerek kabul ettirme yapılmadı. İlk iki taslağın parser/referans düzeltmeleri kayıtlı; onlar için çözücü ağı üretilmedi.</p><p>Bu yeniden dağıtımın bedeli görünür: büyüme medyanı{mesh['normal_growth_before']['median']:.3f}→{mesh['normal_growth_after']['median']:.3f}, maksimumu{mesh['normal_growth_after']['max']:.3f}. Toplam sütun kalınlığı medyan{1000*mesh['total_source_column_arclength_m']['median']:.2f}mm kaldı. İlk y+ kabulü bütün sınır tabakasını çözdüğümüzü kanıtlamaz; normal hız/viskozite profili ve daha düşük büyümeli sistematik aile ayrıca gereklidir.</p><p>{link(OUT/'simulations/m6_wallnormal_mesh_20261024_v3/normal_design_preseal.json','Sonuçtan önce normal tasarım kaydı')} · {link(OUT/'simulations/m6_wallnormal_mesh_20261024_v3/normal_mesh_audit.json','Aralık/büyüme/Jacobian ölçümleri')}</p></section>
<section><h2>Rüzgâr tüneli kıyası: bütün noktalar</h2><img src="../plots/m6_jst_control_Cp_20261024_v2.png" alt="JST ve önceki Roe'nun bütün7 deney kesitiyle kıyası"><img src="../plots/m6_wallnormal_Cp_20261024_v3.png" alt="Normal aralığı değiştirilmiş kaynak M6 ağının aynı deneyle kıyası"><div class="scroll"><table><tr><th>Kesit / eta</th><th>Yüzey</th><th>Nokta</th><th>Önceki Roe RMSE</th><th>JST RMSE</th><th>Normal ağ RMSE</th></tr>{section_rows}</table></div><p>Noktalar, hücum/firar ve şok çevresi dahil korunur. Kaynak .ex −Cp ve Tecplot Cp işareti14 grupta denetlendi. Ana kesit6 eta0,95; Tecplot'taki0,96 yorumu da ayrı duyarlılık çıktısında saklandı. Daha iyi hata veren yorum sonradan seçilmedi. Kaynak yuvarlak uç yaklaşık1,21809m'ye uzanırken deney nominal yarı açıklığı1,1963m'dir; kesitlerdeki kaynak geometri mesafeleri CSV'de tutulur. Bu yaklaşık kaynak yüzeyini deneyin kusursuz CAD eşdeğeri saymıyoruz.</p></section>
<section><h2>Gerçek alanlar ve bağımsız kuvvet okuması</h2><img src="../plots/m6_main_native_fields_20261024_v2.png" alt="Native JST kaynak ağ Cp ve y+"><img src="../plots/m6_normal_native_fields_20261024_v2.png" alt="Native normal ağ Cp ve y+"><table><tr><th>Vaka</th><th>CD basınç</th><th>CD yüzey sürtünmesi</th><th>Bağımsız CL farkı</th><th>Bağımsız CD farkı</th></tr>{force_rows}</table><p>Her duvar yüzeyi tek akış komşusuyla eşleştirildi; normalin yönü akış hücresi merkezinden belirlendi. Cp ve vektör Cf yüzey integrali native kuvvetlerle ayrı karşılaştırıldı. İşaret deney sonucuna uydurulmadı. Basınç bileşeni yalnız dalga sürüklemesi diye etiketlenmez. Kuadratur ve Float32 çıktı hataları var; bu kontrol deneysel kuvvet doğrulaması değildir.</p><p>Her görünüm6.545 gerçek yüzey üçgeniyle Gmsh SDK ve ayrıca native Gmsh programında geri okundu.3B hacim VTU, yeniden başlatma, aynı iterasyonun yüzeyi ve geçmişi korunuyor. Süre sonundaki farklı bir alan eski kuvvet satırıyla birleştirilmedi.</p></section>
<section><h2>Açık kalan teknik iş</h2><p>Son pencerelerde doğrusal çözücü10 adım sınırına dayanıyor. İstenen tolerans1e−5, raporlanan LinSolRes ayrıca ham geçmişte var. Bu bir teşhis ipucudur; sınırın tek neden olduğunu kanıtlamaz. Sonraki kontrollü deneme, aynı mesh/fizik/restart ile yalnız doğrusal iterasyon sınırını artırıp aynı kalıntı/kuvvet kapılarını sınamak olmalıdır.</p><p>Genel kabul için deney farkları, normal katmanın tamamı, aynı geometride sistematik üç ağ ve uzak alan duyarlılığı hâlâ açık. Yakınsamayan iki çözümden GCI/Richardson hata bandı verilmedi. Bu sabit M6 benchmarkı keyfi CAD'den otomatik3B CFD, gerçek İHA veya uçuşa elverişlilik kabulü değildir.</p><p>İlk native başlatma MUSCL_FLOW=YES ile JST'yi reddetti. Gerekli NO ayarı ayrı sürümde uygulandı; hatalı config/log korunuyor. Çalışmayan deneme için Cp/y+ üretilmedi. Temel yazılım kontrolleri26/26 geçti; bu test sonucu fizik kabulünü değiştirmez.</p></section>
<section><h2>İncelenebilir dosyalar ve kaynaklar</h2>{assets_html}<p>{link(REP/'m6_jst_force_integral_20261024_v2.json','JST basınç/sürtünme/moment integrali')} · {link(REP/'m6_wallnormal_force_integral_20261024_v3.json','Normal ağ integrali')} · {link(REP/'m6_followup_integrity_20261024.json','Kaynak, tahmin ve bağlantı bütünlüğü')}</p><p>Kaynaklar gerçekten açıldı: <a href="https://www.grc.nasa.gov/www/wind/valid/m6wing/m6wing.html">NASA: ONERA Test2308 veri ve koşulları</a>, <a href="https://su2code.github.io/documents/SU2_AIAA_SciTech2014.pdf">SU2 yayımlanmış M6 yöntemi, sayfa25/33</a>, <a href="https://raw.githubusercontent.com/su2code/SU2/v8.5.0/TestCases/rans/oneram6/turb_ONERAM6.cfg">SU2 v8.5 M6 config</a>, <a href="https://su2code.github.io/docs_v7/Slope-Limiters-and-Shock-Resolution/">limiter kapsamı</a>. Makaledeki farklı sıcaklık/ağ bu denemeye sessizce taşınmadı; fizik deney skoruna uydurulmadı.</p></section><small>Güncelleme UTC:{now}. Eski raporlar ve gerçek İHA girdileri değişmedi.</small></main></html>'''
    doc=doc.replace('yalnız doğrusal iterasyon sınırını artırıp aynı kalıntı/kuvvet kapılarını sınamak olmalıdır.','aynı restarttan doğrusal iterasyon sınırı10 ve40 için iki ayrı1.000-adımlık koşuyu kıyaslayıp aynı kalıntı/kuvvet kapılarını sınamak olmalıdır.')
    (REP/'m6_24_ekim.html').write_text(doc,encoding='utf-8')
    wrapper='<!doctype html><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=../projects/proje-e9319baef1/reports/m6_24_ekim.html"><title>ONERA M6 gerçek testler</title><a href="../projects/proje-e9319baef1/reports/m6_24_ekim.html">24 Ekim gerçek3B CFD ve deney raporunu aç</a>'
    (ROOT/'outputs/reports/onera_m6_24_ekim.html').write_text(wrapper,encoding='utf-8')
    index={'updated_utc':now,'project_id':'proje-e9319baef1','minimum_qualification_passed':False,'source_RMSE':a['baseline_Cp']['all_point_Cp_RMSE'],
        'JST_RMSE':a['Cp']['all_point_Cp_RMSE'],'normal_RMSE':b['Cp']['all_point_Cp_RMSE'],'normal_yplus_max':b['Cp']['yplus_max'],
        'report':'outputs/projects/proje-e9319baef1/reports/m6_24_ekim.html','RAE_tests_closed_before_M6':True}
    (ROOT/'outputs/reports/m6_followup_index.json').write_text(json.dumps(index,indent=2));print(json.dumps(index,indent=2))
if __name__=='__main__':main()
